-- Generated by tools/dim/import_scans.py. 28 image-only questions: Kimya test toplusu I (2025), bölmə 5.
-- Run once in Supabase SQL Editor. Safe to re-run: the topic is created only if missing, questions are upserted by code.
-- Upload the images (out/upload_kitab/*.png) to the question-images bucket too.
set standard_conforming_strings = on;
begin;

do $$
begin
  if not exists (select 1 from subjects where slug = 'kimya') then
    raise exception 'subjects cədvəlində slug=kimya yoxdur';
  end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
                  where t.typname = 'exam_level' and e.enumlabel = 'qebul') then
    raise exception 'exam_level enum-unda qebul etiketi yoxdur: import dayandırıldı';
  end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
                  where t.typname = 'question_type' and e.enumlabel = 'qapali') then
    raise exception 'question_type enum-unda qapali etiketi yoxdur: import dayandırıldı';
  end if;
end $$;

-- section and topic (only if missing)
insert into topics (subject_id, parent_id, name, sort_order)
select s.id, null, 'Ümumi kimya', 50 from subjects s where s.slug = 'kimya'
on conflict (subject_id, parent_id, name) do nothing;

insert into topics (subject_id, parent_id, name, sort_order)
select s.id, p.id, 'Kimyəvi tənliklər üzrə hesablamalar', 50
  from subjects s join topics p on p.subject_id = s.id and p.parent_id is null and p.name = 'Ümumi kimya'
 where s.slug = 'kimya'
on conflict (subject_id, parent_id, name) do nothing;

insert into questions (code, topic_id, type, body, image_path, options, correct_answer, difficulty, solution,
                       exam_levels, groups, year, source, source_ref, is_active)
select v.code, t.id, 'qapali'::question_type, '', v.image_path, '{"A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}'::jsonb, v.correct,
       3::smallint, null, array['qebul']::exam_level[], '{}'::smallint[], 2025::smallint, 'DİM',
       'Kimya test toplusu I (2025), bölmə 5' || ', sual ' || (regexp_match(v.code, 'Q(\d+)$'))[1]::int, true
  from (values
  ('KT1-S05-Q001', 'KT1-S05-Q001.png', 'E'),
  ('KT1-S05-Q002', 'KT1-S05-Q002.png', 'B'),
  ('KT1-S05-Q003', 'KT1-S05-Q003.png', 'B'),
  ('KT1-S05-Q004', 'KT1-S05-Q004.png', 'D'),
  ('KT1-S05-Q005', 'KT1-S05-Q005.png', 'B'),
  ('KT1-S05-Q006', 'KT1-S05-Q006.png', 'B'),
  ('KT1-S05-Q007', 'KT1-S05-Q007.png', 'B'),
  ('KT1-S05-Q008', 'KT1-S05-Q008.png', 'C'),
  ('KT1-S05-Q009', 'KT1-S05-Q009.png', 'A'),
  ('KT1-S05-Q010', 'KT1-S05-Q010.png', 'A'),
  ('KT1-S05-Q011', 'KT1-S05-Q011.png', 'C'),
  ('KT1-S05-Q012', 'KT1-S05-Q012.png', 'C'),
  ('KT1-S05-Q013', 'KT1-S05-Q013.png', 'A'),
  ('KT1-S05-Q014', 'KT1-S05-Q014.png', 'E'),
  ('KT1-S05-Q015', 'KT1-S05-Q015.png', 'B'),
  ('KT1-S05-Q016', 'KT1-S05-Q016.png', 'E'),
  ('KT1-S05-Q017', 'KT1-S05-Q017.png', 'A'),
  ('KT1-S05-Q018', 'KT1-S05-Q018.png', 'A'),
  ('KT1-S05-Q019', 'KT1-S05-Q019.png', 'B'),
  ('KT1-S05-Q020', 'KT1-S05-Q020.png', 'B'),
  ('KT1-S05-Q021', 'KT1-S05-Q021.png', 'A'),
  ('KT1-S05-Q022', 'KT1-S05-Q022.png', 'C'),
  ('KT1-S05-Q023', 'KT1-S05-Q023.png', 'A'),
  ('KT1-S05-Q024', 'KT1-S05-Q024.png', 'E'),
  ('KT1-S05-Q025', 'KT1-S05-Q025.png', 'E'),
  ('KT1-S05-Q026', 'KT1-S05-Q026.png', 'D'),
  ('KT1-S05-Q027', 'KT1-S05-Q027.png', 'E'),
  ('KT1-S05-Q028', 'KT1-S05-Q028.png', 'D')
       ) as v(code, image_path, correct)
  join subjects s on s.slug = 'kimya'
  join topics sec on sec.subject_id = s.id and sec.parent_id is null and sec.name = 'Ümumi kimya'
  join topics t on t.subject_id = s.id and t.parent_id = sec.id and t.name = 'Kimyəvi tənliklər üzrə hesablamalar'
on conflict (code) do update set
  topic_id = excluded.topic_id, image_path = excluded.image_path, options = excluded.options,
  correct_answer = excluded.correct_answer, source_ref = excluded.source_ref, is_active = excluded.is_active;

do $$
declare n integer;
begin
  select count(*) into n from questions where code in ('KT1-S05-Q001', 'KT1-S05-Q002', 'KT1-S05-Q003', 'KT1-S05-Q004', 'KT1-S05-Q005', 'KT1-S05-Q006', 'KT1-S05-Q007', 'KT1-S05-Q008', 'KT1-S05-Q009', 'KT1-S05-Q010', 'KT1-S05-Q011', 'KT1-S05-Q012', 'KT1-S05-Q013', 'KT1-S05-Q014', 'KT1-S05-Q015', 'KT1-S05-Q016', 'KT1-S05-Q017', 'KT1-S05-Q018', 'KT1-S05-Q019', 'KT1-S05-Q020', 'KT1-S05-Q021', 'KT1-S05-Q022', 'KT1-S05-Q023', 'KT1-S05-Q024', 'KT1-S05-Q025', 'KT1-S05-Q026', 'KT1-S05-Q027', 'KT1-S05-Q028');
  if n <> 28 then
    raise exception 'Gözlənilən 28 sual, bazada % tapıldı: geri alınır', n;
  end if;
end $$;

commit;

select count(*) as yuklenen_sual from questions where code like 'KT1-S05-%';
